"""Compact, platform-aware list credits; never truncate owner-authored text."""

import html
import re

from .config import parse_url
from .model import SyncError

CREDIT_URL = "https://jedirhymetrix.github.io/reelign/"
PROMO = "Your lists. Perfectly aligned. Set up automatic MDBList ↔ Trakt syncing for your own lists or public favorites."
_MARKETING = (f"Powered by [Reelign]({CREDIT_URL}). {PROMO}",
              f"Powered by Reelign ({CREDIT_URL}). {PROMO}")
# Recognize only a complete footer generated by this feature, never a generic
# "Synced from" sentence, arbitrary link, or owner text mentioning Reelign.
_FOOTER = re.compile(r"(?m)^Synced from [^\r\n]+\.\n\n(?:" +
                     "|".join(re.escape(text) for text in _MARKETING) + r")")


def _label(value):
    if not isinstance(value, str):
        raise SyncError("Source attribution label must be text")
    # Metadata is untrusted display content, not Markdown, HTML or control codes.
    text = " ".join("".join(char if ord(char) >= 32 and ord(char) != 127 else " "
                            for char in value).split())
    if not text:
        raise SyncError("Source list or creator has no usable attribution label")
    return text


def _markdown(value):
    return re.sub(r"([\\`*_{}\[\]()#!|~])", r"\\\1", html.escape(value, quote=False))


def compose_description(existing, source, creator, *, formatting="markdown",
                        destination_public=False, limit=10000):
    """Preserve prose and replace exactly one compact source/promo footer.

    Explicit public-source metadata is required before publishing source links
    in a public list. Unknown visibility is treated as private, not as consent.
    """
    if not isinstance(existing, str) or formatting not in {"markdown", "plain"}:
        raise SyncError("Invalid description text or unsupported destination format")
    provider, owner, _ = parse_url(source.url)
    if destination_public:
        public = (source.metadata.get("private") is False if provider == "mdblist"
                  else source.metadata.get("privacy") == "public")
        if not public:
            raise SyncError("Refusing to expose private/unknown source attribution in a public destination")
    title, display = _label(source.name), _label(creator)
    username_only = display.casefold().lstrip("@") == owner.casefold()
    author = f"@{owner}" if username_only else f"{display} (@{owner})"
    profile = f"https://mdblist.com/@{owner}" if provider == "mdblist" else f"https://trakt.tv/users/{owner}"
    if formatting == "markdown":
        author_label = f"@{owner}" if username_only else f"{_markdown(display)} (@{owner})"
        block = (f"Synced from [{_markdown(title)}]({source.url.rstrip('/')}) by "
                 f"[{author_label}]({profile}).\n\n{_MARKETING[0]}")
    else:
        block = (f"Synced from {title} ({source.url.rstrip('/')}) by {author} "
                 f"({profile}).\n\n{_MARKETING[1]}")
    matches = list(_FOOTER.finditer(existing))
    if len(matches) > 1:
        raise SyncError("Multiple managed credit blocks found; review description before syncing")
    if matches:
        match = matches[0]
        result = existing[:match.start()] + block + existing[match.end():]
    else:
        result = existing + ("\n\n" if existing else "") + block
    if type(limit) is not int or limit < 1 or len(result) > limit:
        raise SyncError("Description plus attribution exceeds safe length; shorten owner text or disable attribution")
    return result